dashboard-data.filter:
((.range) // "24h") as $range | (if $range == "24h" then 86400 elif $range == "7d" then 604800 elif $range == "30d" then 2592000 else 0 end) as $window | (now - $window) as $cutoff | {
    range: $range,
    list: [ (.allCompositions // [])[] | select($window == 0 or (((.ts // "") | (fromdateiso8601? // 0)) >= $cutoff)) ]
  }
